%[text] # Observations
%[text] - Deliberately solves the problem twice: first with copy-pasted blocks for each time value, then again with a loop
%[text] - The copy-paste version makes the repetition visible — same formula, four times, only `t` changes
%[text] - His own text narrates the insight: *"After that I will consider making a loop to integrate all those lines in one graph"* — this is exactly the motivation the course is trying to build
%[text] - Good example of using a live script as a notebook: writing out your reasoning, not just the final answer \
%%
%[text]{"align":"center"} # PROBLEM 3
%[text] There is two different ways to solve this exercise. First I´ll solve separate each graph to see how does the velocity change as a function of the distance for each value of time. After that I will consider making a loop to integrate all those lines in one graph.
%[text] ![](text:image:9a3b)                                     v in m/s
figure(1) %[output:6c546ba1]
t= 0;
x= linspace (0,4,100);
v= ((10+0.2*t)*pi) ./ ((pi/4)*((4-0.25*x).^2));
plot (x,v,"o") %[output:6c546ba1]
xlabel ("distance in axis x") %[output:6c546ba1]
ylabel ("velocity") %[output:6c546ba1]
grid ("on") %[output:6c546ba1]
%[text] 
t= 10;
x= linspace (0,4,100);
v= ((10+0.2*t)*pi) ./ ((pi/4)*((4-0.25*x).^2));
plot (x,v,"-o") %[output:50442210]
xlabel ("distance in axis x") %[output:50442210]
ylabel ("velocity") %[output:50442210]
grid ("on") %[output:50442210]
%[text] 
t= 20;
x= linspace (0,4,100);
v= ((10+0.2*t)*pi) ./ ((pi/4)*((4-0.25*x).^2));
plot (x,v,"s") %[output:8b1b875b]
xlabel ("distance in axis x") %[output:8b1b875b]
ylabel ("velocity") %[output:8b1b875b]
grid ("on") %[output:8b1b875b]
%[text] 
t= 30;
x= linspace (0,4,100);
v= ((10+0.2*t)*pi) ./ ((pi/4)*((4-0.25*x).^2));
plot (x,v,"-s") %[output:25e156ad]
xlabel ("distance in axis x") %[output:25e156ad]
ylabel ("velocity") %[output:25e156ad]
grid ("on") %[output:25e156ad]
%%
%[text] - Another way to solve the exercise is making a loop \
figure(2) %[output:202bb459]
tiempo = linspace (0,30,4);         %time
for ii = 1:length(tiempo)
    t = tiempo(ii);
   x= linspace (0,4,100);
   v= ((10+0.2*t)*pi) ./ ((pi/4)*((4-0.25*x).^2));
   plot (x,v) %[output:202bb459]
   hold ("on")
xlabel ("distance in axis x")
ylabel ("velocity")
grid ("on")
end
legend('t=0 s','t=10 s','t=20 s','t=30 s') %[output:202bb459]
%%
%[text] 
%[text] ![](text:image:95a1)     a in m/s^2
%[text] for the acceleration we are just going to use the loop form
%[text] Variable time is already defined by tiempo= \[0 10 20 30\]
figure(3) %[output:7c4faff2]
for ii = 1:length(tiempo)
    t = tiempo(ii);
    x = linspace (0,4,100);
    a = ((0.5)./((4-0.25*x).^2)) + ((0.5 * ((24)+0.5*t)^2)./((2-(0.125*x)).^5));    
    plot (x,a) %[output:7c4faff2]
        hold ("on")
    xlabel ("distance in axis x")
ylabel ("acceleration")
grid ("on")
end
legend('t=0 s','t=10 s','t=20 s','t=30 s') %[output:7c4faff2]

